struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    hexi::pmc::buffer_adaptor adaptor(buffer);
    hexi::pmc::binary_stream stream(adaptor);

    NetworkPacket packet;

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using the length prefix
    stream >> packet.username;

    // Read the score count, then use read_container to read the scores vector
    uint32_t score_count;
    stream >> score_count;
    packet.scores.resize(score_count);
    for (uint32_t i = 0; i < score_count; ++i) {
        stream >> packet.scores[i];
    }

    // Read the metadata string as null-terminated for zero-copy
    const char* metadata_ptr = reinterpret_cast<const char*>(stream.current());
    packet.metadata = std::string(metadata_ptr);
    // Advance the stream past the null-terminated string
    size_t metadata_len = packet.metadata.length() + 1; // Include null terminator
    stream.skip(metadata_len);

    // Skip any remaining padding bytes (if any)
    // Assuming the packet structure is fixed and we know the expected size,
    // or we just consume what's left in the buffer
    // Since no specific padding info is given, we'll assume the stream is correctly positioned

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    hexi::pmc::buffer_adaptor adaptor(buffer);
    hexi::pmc::binary_stream stream(adaptor);

    PacketInfo info;

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto packet_id_span = stream.span<uint32_t>();
    info.packet_id = *packet_id_span.data();
    stream.skip(sizeof(uint32_t));

    // Read username using prefixed adaptor to get a string_view
    info.username = stream.prefixed<std::string_view>();

    // Skip the scores vector without reading its elements
    // Read count, then skip the data
    uint32_t score_count;
    stream >> score_count;
    stream.skip(score_count * sizeof(uint32_t));

    return info;
}
