struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Check if we have enough data for the header
    const size_t header_size = sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint16_t);
    if (adaptor.size() < header_size) {
        throw std::runtime_error("Not enough data in buffer for packet header");
    }

    // Get the read pointer
    const uint8_t* read_ptr = adaptor.data();

    // Create a zero-copy view of the header
    std::span<const uint8_t> header_span(read_ptr, header_size);

    // Parse the header fields
    PacketHeader header;
    hexi::buffer_adaptor header_adaptor(header_span);
    hexi::binary_stream header_stream(header_adaptor);

    header_stream >> header.magic >> header.version >> header.flags;

    return header;
}
