#include <string_view>

struct MessagePacket {
    uint32_t header;
    std::string_view message;
};

MessagePacket read_header_and_message(const std::span<const uint8_t> buffer) {
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    uint32_t header;
    stream >> header;

    std::string_view message = stream.view();
    // Find the null terminator
    size_t null_pos = message.find('\0');
    if (null_pos != std::string_view::npos) {
        message = message.substr(0, null_pos);
    }

    return {header, message};
}
