```python
#include <hexi/allocators/block_allocator.h>
#include <cstdint>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    hexi::block_allocator<int, element_count> allocator;

    // Allocate all elements to empty the free list
    std::array<int*, element_count> pointers;
    for(size_t i = 0; i < element_count; ++i) {
        pointers[i] = allocator.allocate();
        *pointers[i] = static_cast<int>(i);
    }

    // Deallocate all elements to fill the free list
    // This demonstrates the push() behavior as each deallocation
    // adds the block back to the free list
    for(size_t i = 0; i < element_count; ++i) {
        allocator.deallocate(pointers[i]);
    }

    // Re-allocate to demonstrate pop() behavior
    // Each allocation removes a block from the free list
    for(size_t i = 0; i < element_count; ++i) {
        int* ptr = allocator.allocate();
        *ptr = static_cast<int>(i * 2);
        allocator.deallocate(ptr); // Return to free list
    }
}

