```cpp
#include <hexi/file_buffer.h>
#include <cstdint>
#include <filesystem>

int32_t read_int32_from_file(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        throw std::runtime_error("Failed to open file for reading int32");
    }

    hexi::binary_stream stream(buffer);
    int32_t value = 0;
    stream >> value;

    return value;
}

float read_float_from_file(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        throw std::runtime_error("Failed to open file for reading float");
    }

    hexi::binary_stream stream(buffer);
    float value = 0.0f;
    stream >> value;

    return value;
}
```

