#include <cassert>

std::size_t write_multiple_chunks(const std::vector<std::vector<uint8_t>>& chunks) {
    // Calculate total size needed
    std::size_t total_size = 0;
    for (const auto& chunk : chunks) {
        total_size += chunk.size();
    }

    // Create buffer with enough capacity
    std::vector<uint8_t> buffer(total_size);
    hexi::pmc::buffer_write_adaptor writer(buffer);

    // Write each chunk separately
    for (const auto& chunk : chunks) {
        // Check available space before writing
        assert(writer.free() >= chunk.size());

        // Copy data to buffer
        std::copy(chunk.begin(), chunk.end(), writer.write_ptr());

        // Advance write position
        writer.advance_write(chunk.size());
    }

    // Return final buffer size (amount of data written)
    return writer.size();
}

std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    hexi::pmc::buffer_read_adaptor reader(buffer);
    std::vector<uint8_t> result;

    // Read until buffer is empty
    while (reader.size() > 0) {
        // Determine how much to read in this iteration
        std::size_t to_read = std::min(chunk_size, reader.size());

        // Copy data from buffer to result
        const uint8_t* data_ptr = reader.data();
        result.insert(result.end(), data_ptr, data_ptr + to_read);

        // Advance read position
        reader.advance_read(to_read);
    }

    return result;
}
