struct Header {
    uint32_t magic;
    uint16_t version;
};

Header peek_header_without_reading(const std::vector<uint8_t>& buffer) {
    hexi::pmc::buffer_read_adaptor adaptor(buffer);

    // Use copy() to peek at header without advancing read cursor
    Header header;
    adaptor.copy(&header, sizeof(Header));

    // Use read_ptr() to verify pointer position (should be at start since we didn't consume)
    const uint8_t* ptr = adaptor.read_ptr();
    // Verify that ptr points to the beginning of our buffer
    if (ptr != buffer.data()) {
        throw std::runtime_error("Read pointer is not at expected position");
    }

    return header;
}

std::vector<uint8_t> peek_then_conditionally_read(const std::vector<uint8_t>& buffer) {
    hexi::pmc::buffer_read_adaptor adaptor(buffer);

    // Peek at first byte without consuming
    uint8_t first_byte;
    adaptor.copy(&first_byte, sizeof(uint8_t));

    // Conditionally read more data based on peeked value
    std::vector<uint8_t> result;
    if (first_byte == 0xFF) {  // Example condition
        // Read more data since condition is met
        result.resize(buffer.size());
        adaptor.read(result.data(), buffer.size());
    } else {
        // Just read the first byte
        result.resize(sizeof(uint8_t));
        adaptor.read(result.data(), sizeof(uint8_t));
    }

    return result;
}
