import os
import sys
import re
from pathlib import Path

def process_file(file_path):
    """Process a single C++ file to update Hexi library usage."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        print(f"Error reading {file_path}: {e}")
        return False

    # Pattern to match hexi::endian::conversion::little_to_native(...) calls
    pattern = r'hexi::endian::conversion::little_to_native\(\s*([^)]+)\s*\)'

    # Replace with hexi::endian::little_to_native_inplace(...)
    updated_content = re.sub(pattern, r'hexi::endian::little_to_native_inplace(\1)', content)

    # Check if any replacements were made
    if updated_content != content:
        try:
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(updated_content)
            print(f"Updated: {file_path}")
            return True
        except Exception as e:
            print(f"Error writing {file_path}: {e}")
            return False
    else:
        print(f"No changes needed: {file_path}")
        return False

def main():
    """Main function to process files or directories."""
    if len(sys.argv) < 2:
        print("Usage: python update_hexi_usage.py <file_or_directory>...")
        sys.exit(1)

    files_updated = 0

    for arg in sys.argv[1:]:
        path = Path(arg)
        if not path.exists():
            print(f"Path does not exist: {path}")
            continue

        if path.is_file() and path.suffix in ['.cpp', '.h', '.hpp']:
            if process_file(path):
                files_updated += 1
        elif path.is_dir():
            # Recursively find all .cpp, .h, .hpp files
            for file_path in path.rglob('*'):
                if file_path.suffix in ['.cpp', '.h', '.hpp']:
                    if process_file(file_path):
                        files_updated += 1
        else:
            print(f"Skipping unsupported file type: {path}")

    print(f"\nTotal files updated: {files_updated}")

if __name__ == "__main__":
    main()

